class Solution:
    def reorderLogFiles(self, logs: list[str]) -> list[str]:
        def get_key(log: str):
            ident, rest = log.split(" ", 1)
            if rest[0].isdigit():
                return (1,)
            return (0, rest, ident)
        return sorted(logs, key=get_key)

class Solution {
public:
    vector<string> reorderLogFiles(vector<string>& logs) {
        vector<string> letter_logs, digit_logs;
        for (const string& log : logs) {
            size_t pos = log.find(' ');
            if (isdigit(log[pos + 1])) {
                digit_logs.push_back(log);
            } else {
                letter_logs.push_back(log);
            }
        }
        stable_sort(letter_logs.begin(), letter_logs.end(), [](const string& a, const string& b) {
            size_t pA = a.find(' '), pB = b.find(' ');
            string bodyA = a.substr(pA + 1), bodyB = b.substr(pB + 1);
            if (bodyA != bodyB) return bodyA < bodyB;
            return a.substr(0, pA) < b.substr(0, pB);
        });
        letter_logs.insert(letter_logs.end(), digit_logs.begin(), digit_logs.end());
        return letter_logs;
    }
};

class Solution {
    public String[] reorderLogFiles(String[] logs) {
        Arrays.sort(logs, (a, b) -> {
            String[] splitA = a.split(" ", 2);
            String[] splitB = b.split(" ", 2);
            boolean isDigitA = Character.isDigit(splitA[1].charAt(0));
            boolean isDigitB = Character.isDigit(splitB[1].charAt(0));

            if (!isDigitA && !isDigitB) {
                int cmp = splitA[1].compareTo(splitB[1]);
                if (cmp != 0) return cmp;
                return splitA[0].compareTo(splitB[0]);
            }
            if (!isDigitA && isDigitB) return -1;
            if (isDigitA && !isDigitB) return 1;
            return 0;
        });
        return logs;
    }
}

var reorderLogFiles = function(logs) {
    const letterLogs = [];
    const digitLogs = [];
    for (const log of logs) {
        const space = log.indexOf(' ');
        if (log[space + 1] >= '0' && log[space + 1] <= '9') {
            digitLogs.push(log);
        } else {
            letterLogs.push(log);
        }
    }
    letterLogs.sort((a, b) => {
        const sA = a.indexOf(' ');
        const sB = b.indexOf(' ');
        const bodyA = a.slice(sA + 1);
        const bodyB = b.slice(sB + 1);
        if (bodyA !== bodyB) return bodyA.localeCompare(bodyB);
        return a.slice(0, sA).localeCompare(b.slice(0, sB));
    });
    return letterLogs.concat(digitLogs);
};
